Student = {'Ravi', 'Meera'}
Book = {'book1', 'book2'}
Reads = {('Ravi', 'book1'), ('Meera', 'book2')}
Reads2 = {('Ravi', 'book1')}

def students_with_a_book(R):
    return sum(1 for x in Student if any((x, y) in R for y in Book))

def books_read_by_all(R):
    return sum(1 for y in Book if all((x, y) in R for x in Student))

print(len(Student))
print(len(Book))
print(students_with_a_book(Reads))
print(books_read_by_all(Reads))
print(students_with_a_book(Reads2))
